const COMMUNITY_RANK=[["Old Town / Meadowview / Los Ranchitos", "Temecula", "Temecula Valley Unified", "Great Oak HS (#212 CA)", "Low (~1.05%, little/no CFD)", "District ranks #78 among CA public school districts — top 20% statewide."], ["Roripaugh Ranch / Sommer's Bend", "Temecula", "Temecula Valley Unified", "Chaparral HS (#396 CA)", "Med-High (~1.3–1.6%, active CFD)", "Same district as Old Town, higher CFD load — school access identical, tax load is the real differentiator here."], ["Spencer's Crossing", "Winchester", "Menifee Union / Perris Union HSD", "Verify current HS assignment", "High (~2.2% combined)", "Menifee Union SD territory extends here — confirm the exact attendance boundary before advising on schools."], ["French Valley (unincorporated)", "French Valley", "Menifee Union SD (elementary) / boundary-dependent HS", "Verify — boundary straddles districts", "Varies by parcel", "Sits between Temecula Valley USD and Menifee Union SD service areas — always confirm exact district by address, not by community name."], ["Murrieta core", "Murrieta", "Murrieta Valley Unified", "Murrieta Valley HS — verify current CA rank", "Med (~1.15% base, CFD varies by tract)", "Well-regarded district; pull a current Niche/US News rank before quoting a specific number to a client."], ["Canyon Lake / Lakeland Village", "Wildomar", "Lake Elsinore Unified", "Elsinore HS — verify current CA rank", "Low-Med (~1.02% base)", "LEUSD serves the majority of Wildomar and all of Canyon Lake/Lakeland Village."], ["Lake Elsinore core", "Lake Elsinore", "Lake Elsinore Unified", "Elsinore HS — verify current CA rank", "Low-Med (~1.02% base, CFD 89-1 retired)", "CFD 89-1 was paid off, per LEUSD — a genuine example of an assessment stepping down over time; confirm which CFDs remain active on a given parcel."], ["Menifee core", "Menifee", "Menifee Union SD (elem) / Perris Union HSD", "Verify current HS rank", "Med (~1.158% base)", "Menifee Union SD's boundary reaches into Murrieta, Wildomar, and French Valley — district ≠ city name here."], ["Coastal/core San Diego (older neighborhoods)", "San Diego", "San Diego Unified", "Varies widely by neighborhood", "Low (~1.05–1.15%, mostly no CFD in older core)", "Older San Diego neighborhoods generally carry little to no Mello-Roos versus new-construction communities further out."], ["Eastlake", "Chula Vista", "Sweetwater Union High School District", "Eastlake HS (#175 CA)", "Med-High (~1.5–1.8%, CFD common in Eastlake tracts)", "Highest-ranked high school of the three Chula Vista schools compared here — worth the tax-load tradeoff for school-focused buyers."], ["Otay Ranch (incl. Village 3)", "Chula Vista", "Sweetwater Union High School District", "Otay Ranch HS (#400 CA)", "High (~1.6–1.8%, CFD 18-M confirmed active)", "Confirmed active CFD (18-M, Village 3) — pull the exact bond schedule before quoting a payment."], ["Olympian / southern Chula Vista", "Chula Vista", "Sweetwater Union High School District", "Olympian HS (#261 CA)", "Med (~1.5–1.7%, verify per-tract CFD)", "Middle of the three Chula Vista schools compared here on both rank and typical tax load."], ["4S Ranch / Del Sur", "San Diego (92127)", "Poway Unified", "Del Norte HS — Poway Unified, #15 CA / A+", "High (~1.5–2.0%, CFD common — verify per-tract, e.g. 92127 corridor)", "Poway Unified rated A+ by Niche, #2 in San Diego County / #15 statewide — one of the strongest CFD-for-schools trades in the county."], ["Carmel Valley / Pacific Highlands Ranch", "San Diego", "San Dieguito Union High School District", "Torrey Pines / Canyon Crest HS — district #1 in county / #3 CA", "High (~1.5–2.0%, CFD common in newer Carmel Valley tracts)", "San Dieguito Union HSD is the top-rated district in San Diego County per Niche (A+, #3 statewide) — the highest school-quality ceiling on this list."], ["San Elijo Hills", "San Marcos", "San Marcos Unified", "Mission Hills HS — San Marcos USD, A / top-5 county", "Med-High (~1.4–1.7%, CFD active in San Elijo Hills — bonds refinanced 2018, lowering rates for some parcels)", "San Marcos Unified rated A by Niche — a step below San Dieguito/Poway but still strong, often at a lower entry price point."], ["Carlsbad (village + newer tracts)", "Carlsbad", "Carlsbad Unified", "Carlsbad HS — Carlsbad USD, A+ / top-3 county", "Varies (~1.1–1.8% depending on tract: older village low/no CFD, newer tracts active CFD)", "Carlsbad Unified rated A+ by Niche — coastal premium plus school premium; verify CFD status by exact tract, older village core is largely CFD-free."], ["Santaluz / Black Mountain Ranch", "San Diego (92127/92130)", "Poway Unified", "Del Norte HS — Poway Unified, #15 CA / A+", "High (~1.5–2.0%, CFD common)", "Same top-tier Poway Unified access as 4S Ranch/Del Sur, higher-end price point."], ["Harmony Grove", "Escondido", "San Dieguito Union HSD (boundary-dependent)", "Verify — near San Dieguito/Escondido Union boundary", "Med-High (~1.5–1.7%, CFD common in newer Harmony Grove tracts)", "Sits near the San Dieguito Union HSD boundary — confirm exact attendance area by parcel before advising a school-focused buyer."]];
const VA_CHECKLISTS=[{"n": 1, "t": "First-Time VA Purchase (Standard)", "note": "Applies to a first-time VA loan user, single-family primary residence, no prior VA use, W-2 income, and no significant derogatory credit.", "items": ["Order COE via WebLGY or ACE — confirm full entitlement, no prior use, and character of discharge (honorable or general under honorable conditions)", "Confirm VA funding fee tier: first use, 0% down = 2.15%; confirm disability exemption if applicable (request VA award letter)", "Enter income into ARIVE 1003 exactly as documented — base pay, BAH, BAS separately; apply 125% gross-up to non-taxable allowances before AUS run", "Check CAIVRS — no outstanding VA, FHA, USDA, or federal debt in default", "Pull tri-merge credit report; review 24-month payment history and overall pattern", "Identify all medical collections — confirm they are disregardable (not reduced to judgment); document on Form 26-6393", "Calculate family size: all household members including all children, any dependent parents, and non-obligated spouse", "Confirm residual income meets or exceeds VA table for region and family size; apply 5% military-facility reduction if applicable", "Structure seller concessions: up to 4% of the lesser of purchase price or appraised value in Bucket 2 (prepaids, buydown, funding fee, closing costs)", "Review property: single-family, VA MPR-compliant, primary residence only; confirm not in a flood zone requiring flood insurance, which adds to PITI", "Run DU and LPA; compare results; submit to whichever produces Approve/Eligible with best conditions; log AUS results in ARIVE", "Order appraisal through the AMC immediately after contract — VA appraisers are in high demand; do not wait for AUS approval", "Issue Loan Estimate within 3 business days of application with funding fee correctly disclosed", "Submit to underwriter with complete stacking order: COE, 1003, 26-1802a, income docs, asset docs, AUS, appraisal, title commitment, 26-6393", "Clear all UW conditions within 48 hours; confirm funding fee remittance to VA within 15 days of closing"]}, {"n": 2, "t": "VA IRRRL (Interest Rate Reduction Refinance Loan)", "note": "", "items": ["Confirm existing VA loan — pull servicer payment history; loan must be current at application and must have been current for last 6 consecutive months", "Verify occupancy: Veteran must have previously occupied property as primary; currently rented is acceptable on IRRRL (exception to standard occupancy rule)", "Confirm net tangible benefit: new rate must be at least 0.5% lower than existing rate (fixed-to-fixed); or ARM to fixed (any lower rate qualifies)", "Recoupment: all closing costs must be recouped within 36 months from new monthly savings (P&L reduction), per VA regulations", "Confirm funding fee: 0.50% for IRRRL; may be financed into the new loan amount", "No cash out permitted — IRRRL is rate/term only; any cash out requires a full VA Cash-Out refinance", "No appraisal required on most IRRRLs — confirm with specific lender/investor (some lenders still require AVM or appraisal based on overlay)", "Reduced income documentation: income does not need to be re-verified on IRRRL; confirm with investor as some apply overlays requiring income verification", "Credit not re-underwritten on most IRRRLs — confirm with investor; pull credit if required by lender overlay", "Closing Disclosure must comply with TRID; confirm no prepayment penalty on existing loan, no balloon payment on new loan", "Order title update; confirm no new liens on property since original closing", "Fund and remit 0.50% funding fee to VA FFPS within 15 calendar days of closing"]}, {"n": 3, "t": "VA Cash-Out Refinance", "note": "", "items": ["Confirm Veteran is current occupant (primary residence) — cash-out is not available for non-owner-occupied properties", "Pull COE — verify eligibility and entitlement; confirm funding fee tier (Type II cash-out: 2.15% first use, 3.30% subsequent use)", "Order full appraisal — cash-out loan amount cannot exceed appraised value (VA allows up to 100% LTV on cash-out)", "Full credit underwrite required — same as purchase: credit, income, DTI, residual income, CAIVRS", "Calculate family size and residual income — residual income is the primary VA qualifying metric even on refis", "Confirm use of cash proceeds — no restrictions on use of VA cash-out proceeds; document in file for compliance record", "Check seasoning: existing mortgage must have been in place a minimum of 210 days from first payment date; confirm with investor", "Confirm net tangible benefit for cash-out: disclose clearly that the new loan is a higher balance at market rate vs. the existing loan", "Distinguish Type I vs. Type II Cash-Out: Type I = new loan amount does not exceed existing balance (rate/term with cash-out option); Type II = new loan exceeds existing balance (full cash-out); funding fee is the same for both after VA 2019 changes", "Run DU or LPA — confirm AUS output; manual underwrite if AUS produces Refer", "Submit full stacking order per Chapter 4; confirm disclosure of existing loan payoff amount on Closing Disclosure"]}, {"n": 4, "t": "Second-Tier Entitlement / Two Active VA Loans", "note": "", "items": ["Confirm: Veteran has an existing VA loan on Property A (not sold/paid off), and is purchasing Property B as a new primary residence (PCS move, job relocation, or family size change — document reason)", "Pull COE — calculate remaining entitlement after first loan: County Limit − (First Loan Entitlement Used) = Available Entitlement", "Calculate the maximum VA guaranty available on Property B: 25% of the county conforming limit for the new county, minus the entitlement used on Property A", "If available entitlement covers 25% of new purchase price: no down payment; if not: Veteran must pay 25% of the shortfall as a down payment", "Confirm Property A will not be sold — the existing VA mortgage stays in place; the existing PITI on Property A IS a monthly debt obligation for DTI", "Include Property A payment in DTI and residual income analysis; this is the most common underwriting error on two-VA-loan files", "If Veteran intends to rent Property A: rental income may offset Property A PITI with a current lease and 30% vacancy/maintenance deduction; no management experience required for VA", "Calculate funding fee: standard purchase tier applies to Property B (2.15% first use if never used before on first loan; 3.30% if this is the second use)", "Run AUS — confirm DU or LPA handles dual-VA-loan scenario correctly; enter Property A as a departing residence with rental income if applicable", "Document PCS orders, new duty station assignment letter, or other occupancy justification for Property B as primary residence in the loan file"]}, {"n": 5, "t": "VA Construction (Two-Time Close)", "note": "", "items": ["Confirm statutory authority: 38 U.S.C. § 3710(a)(1)(3); transaction is treated as a purchase in WebLGY ('new construction and purchase')", "Verify builder qualifications: licensed, bonded, insured per state/local requirements; builder ID no longer required for regular VA loans (Circular 26-25-1, effective March 31, 2025); still required for SAH and NADL", "Order appraisal 'based on plans and specs' if appraisal can be completed before foundation is poured; otherwise wait and order as 'built less than 1 year and never occupied'", "Confirm eligibility: full COE, entitlement confirmed, CAIVRS clear", "Initial closing: non-VA construction loan closes; VA permanent takeout closes at construction completion", "At permanent VA close: re-qualify borrower; order appraisal if required; confirm CO or inspection reports satisfy VA warranty/inspection requirement", "Warrant requirement: CO from local authority, or inspection reports from local authority, or 10-year HUD insured protection plan plus 1-year VA builder's warranty", "Funding fee: due within 15 calendar days of VA permanent closing", "Land ownership may count as equivalent down payment for funding fee reduction if appraised and value reduces LTV below 5% or 10% thresholds", "Submit full stacking order to VA within 60 days of clear final compliance inspection report"]}, {"n": 6, "t": "VA One-Time Close (OTC) Construction Loan", "note": "Note: VA OTC was discontinued by most lenders in May 2025 due to secondary market risk concerns; a standardized program was re-launched in 2026. Confirm availability with wholesale channel before advising borrowers.", "items": ["Confirm OTC lender/investor availability in your wholesale channel — not all lenders offer VA OTC; most require 620+ credit, 41-50% DTI cap, 2-6 months reserves", "OTC structure: land, construction, and permanent mortgage close simultaneously; one appraisal, one set of closing costs, one funding fee", "Rate locked at closing — protects borrower against rate rises during build; confirm float-down availability with lender", "Borrower does NOT make mortgage payments during construction — interest accrues on drawn funds only; structured into loan", "Funding fee: due within 15 days of loan closing, NOT tied to construction start or completion", "Builder must be an independent entity — owner-builder not allowed on OTC; fixed-price contract required (cost-plus ineligible at most lenders)", "Loan converts automatically to permanent at CO — no re-qualification, no second closing, no second set of closing costs", "Change orders after appraisal cannot be financed — must be paid out of pocket; advance appraiser approval required for all change orders", "Guaranty not issued until clear final compliance inspection received; both loan types must be reported to VA within 60 days of clear final inspection", "Contingency reserve: negotiate minimum 2-5% on top of contract price; document in loan file"]}, {"n": 7, "t": "VA Loan Assumption (Seller or Buyer Perspective)", "note": "See Chapter va20 (The VA Loan Assumption) for the full step-by-step assumption procedure, entitlement table, fees, and divorce scenarios.", "items": ["Confirm loan commitment date: post-March 1, 1988 requires servicer/VA approval; pre-1988 is freely assumable with no funding fee", "Pull COEs for both seller and buyer (if buyer is a veteran) as early as possible", "Obtain and review VA Form 26-10291 (Entitlement Acknowledgement) with seller before contract signing", "Confirm buyer's credit, income, and DTI will qualify under VA Ch. 4 standards (same as purchase underwrite)", "Structure for SOE if buyer is a veteran with sufficient entitlement — this is the seller's best outcome", "Confirm assumption funding fee: 0.5% of loan balance, paid in cash at closing (not financeable); confirm exemption if buyer has SC disability", "Submit assumption application to servicer immediately at contract signing; document every submission date", "Budget for 60-90 day closing timeline; write purchase contract accordingly", "If secondary borrowing needed for equity gap: confirm junior lien compliance with Circular 26-24-17", "For divorce: confirm which scenario applies; confirm no funding fee for divorce-related assumptions", "Processing fee caps: $300 auto authority servicer; $250 non-auto authority", "Confirm stacking order package assembled per Circular 26-23-10 Exhibit A before closing submission"]}, {"n": 8, "t": "VA Manufactured Home Loan", "note": "", "items": ["Confirm property classification: permanently affixed to land (titled as real property), not a personal property MH loan; must be a real property transaction", "Verify property is double-wide or larger (most VA MH lenders require this); confirm construction date post-June 15, 1976 (HUD code compliance)", "Confirm it is or will be the Veteran's primary residence", "Appraisal: VA requires an appraiser with manufactured housing designation; order through AMC with specific MH competency request", "MH minimum property requirements apply (MPRs) — skirt, permanent foundation, utility connections, no wheels/axles", "Check lender overlays: many VA lenders do NOT fund manufactured homes; confirm with wholesale partners before proceeding", "Confirm land ownership: both land and home must be purchased together, or Veteran already owns the land", "Title: must be de-titled from personal property to real property before closing (recorded deed of affixation in most states)", "Standard income, credit, and residual income analysis applies — no separate MH underwriting standard", "Funding fee: same as standard VA purchase (2.15% first use)"]}, {"n": 9, "t": "VA Multi-Unit (2-4 Family) Purchase", "note": "", "items": ["Confirm Veteran will occupy one unit as primary residence — VA requires owner-occupancy of one unit on all multi-family VA purchases", "Order VA appraisal for multi-unit property; confirm local rental market data will support rental income assumptions", "Calculate rental income: 75% of gross monthly rents per current lease (or market rent from appraisal if no existing tenants); include in effective income calculation", "Include PITI on the entire property in DTI (not just the unit occupied)", "Confirm utilities/maintenance in residual income calculation: larger properties have higher maintenance cost factors", "Confirm no HOA on multi-unit property that would add to monthly obligations", "Check lender overlays: some VA lenders limit to 2-unit; fewer lenders fund 3-4 unit VA purchases — confirm availability", "Funding fee: same as standard VA purchase; multi-unit purchase does not carry a higher funding fee", "Confirm Veteran will move into a unit within 60 days of closing; document occupancy intent on 26-6393", "State landlord-tenant law compliance: review with borrower any required notices, lease forms, or habitability requirements for existing tenants"]}, {"n": 10, "t": "VA Condo Purchase", "note": "", "items": ["Confirm condo project approval status in VA's approved condo list (WebLGY) — MUST be VA-approved before ordering appraisal or proceeding", "If not VA-approved: determine if condo qualifies for Single Unit Approval (SUA) — Circular 26-19-12 allows individual unit approval if project meets criteria (10%+ owner-occupied, no more than 35% commercial space, etc.)", "Pull current HOA financials: VA requires HOA is financially sound (adequate reserves, no pending litigation, no delinquency over 15%)", "Confirm project has no more than 49% single-entity ownership of units (prevents single-owner control; VA standard)", "Include full HOA monthly assessment in PITI for qualifying ratios and residual income calculation", "Standard income, credit, DTI, and residual income underwrite applies", "Funding fee: same as standard VA purchase", "Confirm occupancy: condo must be primary residence for VA purchase", "Check HOA documents for any restrictions on VA financing, leasing, or transfer that might conflict with VA assumability or eligibility requirements", "If SUA path: submit complete condo project package to lender/VA early — SUA approval can take 2-4 weeks and should not delay the closing timeline"]}, {"n": 11, "t": "Self-Employed Veteran", "note": "", "items": ["Confirm 2-year self-employment history via 2-year federal tax returns (personal 1040 and business returns if S-corp, partnership, or C-corp)", "Calculate qualifying income: 2-year average of net profit after adding back depreciation, depletion, amortization; subtract business use of home and one-time income/losses", "Confirm business is viable: declining income (Year 2 less than Year 1) requires use of lower year; a significant decline may raise viability concerns", "Pull business bank statements (12-24 months): confirm business deposits support reported income; reconcile YTD P&L to tax return pattern", "CAIVRS: check under both personal SSN and any business EIN if borrower has held an SBA loan or other federally-backed business debt", "Calculate S-corp or partnership pro-rata income: add borrower's W-2 wages from the business plus proportionate share of business income per 1065/1120S; add back depreciation; subtract draws not includable", "Residual income: ensure residual income analysis reflects realistic personal living expenses — self-employed borrowers often have intermingled business/personal accounts that overstate apparent reserves", "Run AUS: DU and LPA may produce Refer on complex self-employment income; prepare for manual underwrite pathway", "Request 3-6 months business bank statements showing consistent revenue and no extraordinary pre-application income spikes", "Document business ownership percentage and confirm Veteran controls the business (25%+ ownership = self-employed treatment)"]}, {"n": 12, "t": "Recently Separated / ETS Veteran", "note": "", "items": ["Confirm DD-214 is in hand — check Block 24 (Character of Discharge: Honorable or General Under Honorable Conditions required) and Block 27 (Reentry Code)", "Confirm 90-day active service for eligibility (or applicable Guard/Reserve minimum); verify with COE request via WebLGY ACE or manual submission", "Employment status: if not yet employed in civilian job, confirm job offer letter with start date within 60 days of closing; document expected income from offer letter", "If employed <1 year in new civilian job: document prior military occupational specialty (MOS) and civilian job field — same/related field allows shortened history requirement", "VA disability rating: if rated disabled pre-discharge (even pending), funding fee exemption may be available; request pre-discharge memorandum rating from VA if claim pending", "Gap in employment between discharge and new civilian job: any gap over 30 days in prior 24 months requires explanation letter; military separation is acceptable reason — document with DD-214", "SCRA: confirm any car loans, student loans, or personal loans taken during active duty may be eligible for SCRA interest rate caps; brief borrower on SCRA rights even though no longer active", "Calculate residual income using anticipated post-employment income; if not yet employed, document housing plan and financial cushion", "Confirm occupancy: recently-separated veteran has 60 days to move in per standard rule; document any delay and reason", "Entitlement: confirm COE reflects no prior VA loan use; if prior use while active, confirm entitlement restoration or calculate remaining/bonus entitlement for new purchase"]}, {"n": 13, "t": "Surviving Spouse", "note": "", "items": ["Confirm eligibility: surviving spouse of veteran who died on active duty or from a service-connected disability; or un-remarried surviving spouse of veteran who was totally disabled at time of death", "Remarriage: surviving spouses who remarried before December 16, 2003 are generally not eligible; remarried after age 57 (on or after December 16, 2003) may be eligible — confirm with VA RLC", "Obtain VA Form 26-1817 (Request for Determination of Loan Guaranty Eligibility — Surviving Spouse) and submit to VA RLC for COE", "Funding fee: surviving spouse receiving DIC (Dependency and Indemnity Compensation) is exempt from the VA funding fee", "Full credit and income underwrite applies: surviving spouse qualifies on their own income, credit, and residual income — the veteran's income is not counted", "DIC is non-taxable income: eligible for 125% gross-up in DTI analysis", "Occupancy: surviving spouse must occupy as primary residence", "Check CAIVRS for prior VA loan associated with the deceased veteran — if a prior VA loan had a claim paid, surviving spouse's entitlement may be affected", "If any pending VA benefits are unresolved: confirm DIC status before issuing pre-approval (DIC confirmation may affect both funding fee and income)", "Military records of the deceased veteran may be needed: DD-214, service/disability records; obtain from National Archives or VA if needed"]}, {"n": 14, "t": "Bankruptcy / Foreclosure Recovery", "note": "See Chapter va05 (Bankruptcy, Foreclosure & Adverse-Event Seasoning) for full details.", "items": ["Chapter 7: confirm discharge date (not filing date) — 2+ years = may be disregarded; 1-2 years = dual-test (re-established credit AND circumstances beyond control); document cause of BK", "Chapter 13: confirm 12+ consecutive months of timely plan payments; obtain trustee/court approval for new credit purchase", "Foreclosure: confirm foreclosure completion date — 2+ years = may be disregarded; 1-2 years = borderline requiring strong compensating factors", "Prior VA loan foreclosure: check COE for entitlement impairment; if VA paid a claim, entitlement restoration requires repayment of the claim", "CAIVRS check is mandatory: a prior VA or FHA loan that resulted in a claim payment will produce a CAIVRS hit — clear CAIVRS before proceeding", "Document cause of adverse event: medical emergency, job loss, deployment, divorce — circumstances beyond control open the early approval pathway", "Re-established credit post-BK/foreclosure: document 12-24 months of clean credit (on-time payments on at least 2-3 accounts)", "Letter of Explanation (LOE): draft proactively at intake, not in underwriting; detail the event, the resolution, and the current financial stability", "Manual underwrite: most BK/foreclosure files within the shorter windows will produce AUS Refer — build the manual underwrite file with all compensating factors documented", "Residual income and assets are the key compensating factors for derogatory credit history in manual underwrite"]}, {"n": 15, "t": "Low Credit Score VA File (<620 Overlay)", "note": "", "items": ["Confirm: VA has NO minimum credit score — the low score is a lender overlay issue, not a VA eligibility issue; find a lender that funds manual underwrites at the borrower's score", "Pull tri-merge report; identify all derogatory items by type — medical collections (disregardable), disputed accounts, judgment, late payments; document the pattern", "Medical collections: disregard all identifiable medical collections not reduced to judgment; note on 26-6393; may materially improve effective risk picture even if score stays low", "Analyze score-suppression: is score suppressed by medical collections that should be disregarded, by active disputes, or by authorized user accounts with negative impact? Rapid rescore may recover 20-50 points", "Rapid rescore strategy: identify 1-3 actionable items (pay down a revolving account below 30%, remove an incorrect item, remove an active dispute); model the score impact before committing to a rescore", "LPA positive cash flow: if borrower has 12 months of documented on-time bank transactions, submit Asset Verification Report (AVR) to LPA — may convert risk class even with low score", "Manual underwrite: prepare compensating factor narrative: strong residual income, liquid reserves, low DTI, stable employment, clean prior housing payment history (12 months on-time rent or mortgage)", "Find a manual-underwrite-friendly VA lender in your wholesale channel; some non-QM VA lenders go as low as 550 with adequate compensating factors", "Document cause of low score on LOE; if score is low due to credit-thin profile (not derogatory), explore alternative credit: 12 months utility, rent, or cell phone payment history"]}, {"n": 16, "t": "High DTI VA File (>45% DTI)", "note": "", "items": ["VA has no hard DTI cap — high DTI is compensable; AUS may approve at 55-60%+ if residual income is strong; document all compensating factors", "Confirm residual income EXCEEDS VA guideline — the primary compensating factor for high DTI is strong residual income; calculate exactly and document on 26-6393", "Non-taxable income gross-up: confirm all BAH, BAS, disability compensation, and other non-taxable income is grossed up by 125% — this is the most underused income lever and directly reduces DTI", "Debt exclusions: co-signed loans with documented 12-month third-party payment history; installment debts with fewer than 10 months remaining; ex-spouse debts assigned by divorce decree with proof of payment; deferred student loans ending 12+ months post-closing", "Seller concessions: increase seller concessions to fund a permanent rate buydown (2-1 or 1-0 temporary buydown funded by seller) — reduces initial monthly payment to meet qualifying ratio", "Permanent rate buydown: evaluate points-to-rate tradeoff; a 0.5% rate reduction on a $400K loan ≈ $130/mo DTI relief", "Increase income sources: confirm all income sources are captured — part-time job, rental income, pension, disability compensation, child support (if 3+ years remaining), VA disability", "AUS strategy: run both DU and LPA; LPA may produce Eligible when DU produces Ineligible on high-DTI files; compare recommendation letters for condition differences", "Manual underwrite at high DTI: requires 2 compensating factors from the VA-defined list; residual income exceeding guideline by at least 20% is the strongest compensating factor", "Refer borrower to debt management if DTI is genuinely unsustainable — a pre-approval that fails in underwriting damages trust more than a referral to credit counseling followed by a successful close in 90 days"]}, {"n": 17, "t": "Low Residual Income", "note": "", "items": ["Confirm family size count is correct — every additional dependent raises the residual income guideline; also confirm no family members can be legitimately excluded", "Apply 5% military-facility reduction if applicable (active duty, retired servicemember, 100% disabled veteran, Medal of Honor recipient with facility access near property)", "Gross up all non-taxable income by 125% — BAH, BAS, disability, DIC; every $100 of grossed-up non-taxable income adds $25 to effective monthly income", "Reduce monthly obligations: identify debt exclusions (co-signed debt, deferred student loans, near-maturity installments)", "Re-evaluate property selection: a lower-priced property reduces PITI and thus reduces the residual income shortfall", "Seller concession for buydown: a temporary 2-1 buydown reduces the qualifying payment (note: residual income uses the fully-indexed payment, not the buydown payment — confirm with lender)", "Additional income sources: rental income from subject property (multi-unit scenario), part-time employment documented for 2 years", "Manual underwrite note: if residual income exceeds the VA guideline by at least 20%, high DTI may still be approved; conversely, residual income below guideline is a harder bar to overcome than high DTI — no automatic override exists", "Document all findings on 26-6393 with explicit residual income calculation showing region, family size, guideline, and actual amount"]}, {"n": 18, "t": "Disputed Appraisal / Low VA Value", "note": "", "items": ["Confirm VA appraised value (NOV) is below contract price — VA loans cannot exceed the appraised value (no LTV waiver); this triggers Tidewater or Reconsideration of Value (ROV) process", "Tidewater process: if the appraiser determines market data will not support the contract price before completing the appraisal, Tidewater notice is issued to the lender/point of contact; provide additional comps within 2 business days", "ROV (Reconsideration of Value): after an NOV is issued below contract price, the lender (not the seller or buyer directly) submits an ROV request to the VA RLC with: at least 3 additional recent comparable sales not used by appraiser, supporting data, and a written justification", "Comp selection for ROV: comps must be from same neighborhood/market area, closed within 90-180 days, similar GLA/lot, similar condition; avoid comps that are clearly inferior or superior without adjustment", "Buyer options if ROV denied: (a) renegotiate purchase price to NOV; (b) buyer pays difference above NOV in cash; (c) walk away per VA appraisal contingency", "Seller renegotiation: use the NOV as leverage; sellers know VA buyers cannot proceed above the NOV without cash; a realistic seller in a normal market will reduce price to NOV", "Second appraisal: VA allows a second appraisal if there is reasonable basis to believe the first was flawed; must be requested through the lender to the VA RLC, not ordered independently", "Appraisal independence: MLO and agent cannot communicate directly with the VA appraiser; all comp submissions must go through the lender's AMC to the VA appraiser or ROV process", "Document all ROV submissions with timestamps; VA ROV review typically takes 5-10 business days"]}];
